#Bigger font
#
# This script creates the violin plot used in the study figure.
# It depends on the prepared analysis dataset generated by data_prep.R.
# If the dataset is not present, the script will first try to run the data
# preparation script automatically.

library(ggplot2)
library(tidyr)
library(dplyr)

# Identify the repository root when the script is run from the repository root
# or one of its parent directories.
find_project_root <- function() {
  cwd <- getwd()
  candidates <- c(
    cwd,
    normalizePath(file.path(cwd, ".."), mustWork = FALSE),
    normalizePath(file.path(cwd, "../.."), mustWork = FALSE)
  )

  for (candidate in candidates) {
    if (file.exists(file.path(candidate, "Data", "MPLUS_scale_ordered_intervals2.dat"))) {
      return(normalizePath(candidate))
    }
  }

  for (candidate in candidates) {
    if (dir.exists(file.path(candidate, "Data")) && file.exists(file.path(candidate, "data_prep.R"))) {
      return(normalizePath(candidate))
    }
  }

  return(normalizePath(cwd))
}

project_root <- find_project_root()
data_file <- file.path(project_root, "Data", "MPLUS_scale_ordered_intervals2.dat")
prep_script <- file.path(project_root, "data_prep.R")

if (!file.exists(data_file)) {
  if (file.exists(prep_script)) {
    message("Prepared dataset not found. Running data_prep.R first...")
    source(prep_script, chdir = TRUE)
  } else {
    stop("Prepared dataset not found and data_prep.R was not found. Run data_prep.R before this figure script.")
  }
}

# Read the prepared analysis file, which stores one row per measurement occasion.
# The file does not include a header row, so we add the column names explicitly.
df_MPlus_scale_intervals_ordered <- read.table(
  data_file,
  sep = "",
  col.names = c("userId", "BO", "VA", "OC", "UC", "MO", "intervaldays"),
  stringsAsFactors = FALSE
)

df_long <- df_MPlus_scale_intervals_ordered %>%
  select(BO, VA, OC, UC, MO) %>%
  pivot_longer(cols = everything(), names_to = "Variable", values_to = "Score") %>%
  mutate(Variable = recode(Variable,
    "BO" = "Boredom",
    "VA" = "Value",
    "OC" = "Overchallenge",
    "UC" = "Underchallenge",
    "MO" = "Motivation"
  ))

df_long$Variable <- factor(
  df_long$Variable,
  levels = c(
    "Boredom",
    "Overchallenge",
    "Underchallenge",
    "Value",
    "Motivation"
  )
)

p <- ggplot(df_long, aes(x = "", y = Score, color = Variable)) +
  geom_violin(fill = NA, trim = TRUE) +
  stat_summary(fun = median, geom = "crossbar", width = 0.1, color = "black") +
  stat_summary(fun = mean, geom = "point", shape = 17, size = 3, color = "black") +
  facet_wrap(~ Variable, nrow = 1) +
  scale_color_manual(values = c(
    "Boredom" = "orange",
    "Value" = "steelblue",
    "Overchallenge" = "red",
    "Underchallenge" = "purple",
    "Motivation" = "forestgreen"
  )) +
  labs(x = "", y = "Score", title = NULL) +
  theme_minimal() +
  theme(
    legend.position = "none",
    strip.text = element_text(size = 16, face = "bold"),
    axis.title.y = element_text(size = 14),
    axis.text.y = element_text(size = 12)
  )

output_file <- file.path(project_root, "violin_panel_colour_bigger.png")
ggsave(output_file, plot = p, width = 12, height = 6, dpi = 300)
